-- Fakt kartochkalarining ruscha matni — 23-partiya:
-- Temur Malik, Shohrux Mirzo, Mirzo Ulug'bek, Qozizoda Rumiy,
-- Boysung'ur Mirzo, Xoja Ahror Valiy, Shayboniyxon, Abdullaxon II.

-- ===== Temur Malik =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда родился Тимур Малик?', fact_ru = 'Год и место моего рождения в источниках точно не записаны. Я жил в XIII веке, и судьба моя тесно связана с городом Худжанд.' WHERE id = 2346;
UPDATE fact_cards SET topic_ru = 'Правление Худжандом', question_ru = 'Правителем какого города был Тимур Малик?', fact_ru = 'Я был правителем Худжандской области. Когда войска Чингисхана вторглись в нашу страну, я решил не сдавать свой город врагу без боя.' WHERE id = 2347;
UPDATE fact_cards SET topic_ru = 'Крепость на острове', question_ru = 'Где располагалась крепость Тимура Малика?', fact_ru = 'Я укрепил крепость на острове посреди Сырдарьи, надвое рассекающей Худжанд. Со мной было более тысячи храбрецов и метких стрелков и около сотни корабельных мастеров.' WHERE id = 2348;
UPDATE fact_cards SET topic_ru = 'Бой с монголами', question_ru = 'Как сражался Тимур Малик против монголов?', fact_ru = 'К Худжанду подошло двадцатитысячное монгольское войско во главе с нойонами Соктэ и Улаком. Мы на судах внезапно нападали на вражеский стан — в одном из боёв пущенная стрела вонзилась в глаз нойону Улаку.' WHERE id = 2349;
UPDATE fact_cards SET topic_ru = 'Суда, обитые войлоком', question_ru = 'Какими были суда Тимура Малика?', fact_ru = 'Мои мастера построили особые суда, поставили на них столбы и обили верх и борта войлоком — вражеские стрелы такие суда не брали. Плывя на этих судах, я со своими воинами нападал на врага.' WHERE id = 2350;
UPDATE fact_cards SET topic_ru = 'Соратник Джалалиддина', question_ru = 'Как Тимур Малик действовал вместе с Джалалиддином Мангуберди?', fact_ru = 'Пройдя трудные пути, я присоединился к Джалалиддину Мангуберди, сражавшемуся с монголами на иранской земле, и продолжил борьбу с монгольскими завоевателями в рядах султана.' WHERE id = 2351;
UPDATE fact_cards SET topic_ru = 'Освобождение Янгикента', question_ru = 'Какой город освободил Тимур Малик от монголов?', fact_ru = 'Позже, отступив, я добрался до Хорезма, собрал там войско, чтобы продолжить борьбу, и вновь двинулся к Сырдарье. Я освободил от врага город Янгикент, покарал изменника-правителя, перешедшего на сторону монголов, и поставил вместо него верного человека.' WHERE id = 2352;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Тимур Малик?', fact_ru = 'В каком году я скончался, в источниках точно не записано — я умер, как умирают все смертные. В предании говорится, что через 15 лет после худжандских событий я в облике дервиша вернулся из Дамаска в родной город.' WHERE id = 2353;

-- ===== Shohrux Mirzo =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Шахрух Мирза?', fact_ru = 'Я родился 20 августа 1377 года в городе Самарканде. Моя юность прошла в Самарканде, там я получил и светское, и духовное образование.' WHERE id = 2314;
UPDATE fact_cards SET topic_ru = 'Мой отец Амир Темур', question_ru = 'Кем был отец Шахруха Мирзы и какой край был ему дан?', fact_ru = 'Я сын сахибкирана Амира Темура. В 1396 году отец дал мне в суюргал край Хорасан, и с этого года я правил этим краем.' WHERE id = 2315;
UPDATE fact_cards SET topic_ru = 'Восшествие на престол', question_ru = 'Когда Шахрух Мирза стал правителем державы Тимуридов?', fact_ru = 'После смерти отца, в марте 1405 года, я взошёл на хорасанский престол как правитель державы Тимуридов. Я велел читать хутбу от своего имени и чеканить монету.' WHERE id = 2316;
UPDATE fact_cards SET topic_ru = 'Как я обустраивал города', question_ru = 'Какие города восстановил Шахрух Мирза?', fact_ru = 'В 1405 году я издал высочайший указ о восстановлении Герата, а в 1407 году — Балха. Город Мерв был отстроен заново, восстановлена оросительная сеть и освоены новые земли.' WHERE id = 2317;
UPDATE fact_cards SET topic_ru = 'Покровительство наукам', question_ru = 'Как развивались наука и культура во времена Шахруха Мирзы?', fact_ru = 'В моё время наука широко развилась в Герате, Самарканде, Бухаре, Мешхеде и Ширазе. Было построено множество медресе, мечетей и ханак, расцвели ремёсла и торговля.' WHERE id = 2318;
UPDATE fact_cards SET topic_ru = 'Мой сын Улугбек', question_ru = 'Чем прославился Улугбек, сын Шахруха Мирзы?', fact_ru = 'Мой сын Мирзо Улугбек построил в Мавераннахре обсерваторию, и там развились точные науки. Я горжусь тем, что мои дети послужили науке и просвещению.' WHERE id = 2319;
UPDATE fact_cards SET topic_ru = 'Послы и мир', question_ru = 'С какими государствами вёл посольские связи Шахрух Мирза?', fact_ru = 'В своей внешней политике я считал главным направлением мир, согласие и дружественные отношения между государствами. Я отправлял послов к правителям Китая, Индии, Египта, Шама, Рума и Дешт-и Кипчака.' WHERE id = 2320;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Шахрух Мирза?', fact_ru = 'Я скончался в 1447 году в городе Рей.' WHERE id = 2321;

-- ===== Mirzo Ulug'bek =====
UPDATE fact_cards SET topic_ru = 'Моё детство с дедом', question_ru = 'В чьём воспитании рос Мирзо Улугбек в детстве?', fact_ru = 'Моё детство прошло при дворе моего деда Амира Темура. Воспитывала меня любимая жена деда — Сарай-Мульк-ханым (Биби-ханым). С дедом я бывал и в дальних походах.' WHERE id = 1702;
UPDATE fact_cards SET topic_ru = 'Мой наставник', question_ru = 'Какой знаменитый учёный был наставником Мирзо Улугбека?', fact_ru = 'В юности моим наставником был знаменитый учёный Казизаде Руми. Он обучил меня наукам математики и астрономии. Позже он стал одним из моих ближайших единомышленников в обсерватории.' WHERE id = 1703;
UPDATE fact_cards SET topic_ru = 'Мой ученик Али Кушчи', question_ru = 'Кто был самым знаменитым учеником Мирзо Улугбека?', fact_ru = 'Самым одарённым моим учеником был Али Кушчи. Он работал в моей обсерватории плечом к плечу со мной. После моей смерти он сберёг моё научное наследие и донёс мой труд «Зидж» до других стран.' WHERE id = 1704;
UPDATE fact_cards SET topic_ru = 'Изречение на портале', question_ru = 'Какие слова начертаны на портале медресе Мирзо Улугбека в Бухаре?', fact_ru = 'На портале медресе, построенного мной в Бухаре, начертаны мудрые слова: «Стремление к знанию — долг каждого мусульманина и каждой мусульманки». Я считал знание необходимым для всех.' WHERE id = 1705;
UPDATE fact_cards SET topic_ru = 'Моя книга по истории', question_ru = 'Какой труд по истории написал Мирзо Улугбек?', fact_ru = 'Я занимался не одной только наукой о звёздах. Я написал и труд по истории под названием «Тарихи арбаа улус», то есть «История четырёх улусов».' WHERE id = 1706;
UPDATE fact_cards SET topic_ru = 'Как вновь нашли мою обсерваторию', question_ru = 'Кто и когда нашёл остатки обсерватории Мирзо Улугбека?', fact_ru = 'Я погиб в 1449 году. Спустя века после моей смерти моя обсерватория оказалась погребена под землёй. В 1908 году археолог Василий Вяткин нашёл её остатки в Самарканде. Сегодня на том месте музей — ты можешь пойти и посмотреть!' WHERE id = 1707;
UPDATE fact_cards SET topic_ru = 'Моё имя сегодня', question_ru = 'Что названо сегодня именем Мирзо Улугбека?', fact_ru = 'Сегодня моим именем названы один из районов Ташкента и Национальный университет Узбекистана. Даже одному из кратеров на Луне учёные дали моё имя.' WHERE id = 1708;

-- ===== Qozizoda Rumiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Казизаде Руми?', fact_ru = 'Я появился на свет в 1337 году в турецком городе Бурса. Позже в поисках знания я отправился в дальние края от родины.' WHERE id = 2274;
UPDATE fact_cards SET topic_ru = 'Мой первый наставник', question_ru = 'Кто был первым наставником Казизаде Руми?', fact_ru = 'Первые уроки я получил у известного энциклопедиста и философа Шамсиддина аль-Фанари. Он помог мне тайно покинуть Турцию, после чего я основательно изучил астрономию и математику в знаменитых медресе Мавераннахра и Хорасана.' WHERE id = 2275;
UPDATE fact_cards SET topic_ru = 'Мой ученик Улугбек', question_ru = 'Какое влияние оказал Казизаде Руми на Улугбека?', fact_ru = 'Я был одним из авторитетных учёных, преподававших астрономию и математику в самаркандском медресе. Заметив редкое дарование Мирзо Улугбека к астрономии, я направил его к глубокому изучению этой науки; он многому у меня научился и считал меня своим наставником.' WHERE id = 2276;
UPDATE fact_cards SET topic_ru = 'Имя «Платон своего времени»', question_ru = 'Каким именем называли Казизаде Руми современники?', fact_ru = 'Современники называли меня «Платоном своего времени». Для меня это было великой честью.' WHERE id = 2277;
UPDATE fact_cards SET topic_ru = 'Руководство обсерваторией', question_ru = 'Кто был поставлен во главе обсерватории Улугбека?', fact_ru = 'Улугбек поставил меня вместе с Гиясиддином Джамшидом Каши во главе Самаркандской обсерватории. Там я руководил работами по изучению звёзд.' WHERE id = 2278;
UPDATE fact_cards SET topic_ru = 'Мои уроки в медресе', question_ru = 'Какую роль играл Казизаде Руми в медресе?', fact_ru = 'В самаркандском медресе я играл важную роль в обучении студентов. Когда в 1420 году строительство медресе было завершено, первый урок в присутствии Улугбека начал я.' WHERE id = 2279;
UPDATE fact_cards SET topic_ru = 'Моя работа над «Зиджем»', question_ru = 'Над каким трудом работал Казизаде Руми?', fact_ru = 'Я деятельно участвовал в работах по составлению звёздных таблиц — «Зиджа» — в Самарканде. После смерти Гиясиддина Джамшида Каши работу по оформлению этого великого труда продолжил я.' WHERE id = 2280;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Казизаде Руми?', fact_ru = 'Я скончался в 1436 году, когда работы по составлению звёздных таблиц шли полным ходом. Это стало большой потерей для моих учеников и сотоварищей.' WHERE id = 2281;

-- ===== Boysung'ur Mirzo =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и в какой семье родился Байсункар Мирза?', fact_ru = 'Я родился в 1397 году. Мой отец — правитель Тимуридов Шахрух Мирза, мать — знаменитая царица Гавхаршад-бегим. Я их средний сын.' WHERE id = 2138;
UPDATE fact_cards SET topic_ru = 'Мой отец и мой дед', question_ru = 'Кем были отец и дед Байсункара Мирзы?', fact_ru = 'Мой отец Шахрух Мирза — четвёртый сын Амира Темура, могущественный правитель державы Тимуридов. Стало быть, великий Амир Темур приходится мне дедом!' WHERE id = 2139;
UPDATE fact_cards SET topic_ru = 'Мои братья', question_ru = 'Кто были братья Байсункара Мирзы?', fact_ru = 'Мой старший брат — знаменитый учёный Улугбек Мирза, его настоящее имя Мухаммад Тарагай. А младший брат — Мухаммад Джуки Мирза. У моей матери Гавхаршад-бегим было три сына и две дочери.' WHERE id = 2140;
UPDATE fact_cards SET topic_ru = 'Покровитель книжного искусства', question_ru = 'В развитие каких искусств внёс вклад Байсункар Мирза в Герате?', fact_ru = 'В Герате я внёс большой вклад в развитие китабата — создания рукописной книги — и искусства миниатюры. Красиво написанные, украшенные книги я ценил превыше всего.' WHERE id = 2141;
UPDATE fact_cards SET topic_ru = 'Работа над «Шахнаме»', question_ru = 'Какую работу проделал Байсункар Мирза с «Шахнаме»?', fact_ru = 'Я собрал разные списки «Шахнаме» Фирдоуси и велел составить, говоря нынешним языком, её научно-критический текст. Эту великую поэму я очень ценил.' WHERE id = 2142;
UPDATE fact_cards SET topic_ru = 'Наш спор с братом', question_ru = 'О каких произведениях спорили Байсункар Мирза и Улугбек?', fact_ru = 'Я ставил «Хамсу» Амира Хосрова Дехлеви выше «Хамсы» шейха Низами, а мой брат Улугбек был сторонником Низами. Мы спорили, сличая две «Хамсы» бейт за бейтом.' WHERE id = 2143;
UPDATE fact_cards SET topic_ru = 'Доверие отца', question_ru = 'Какое поручение дал Шахрух Байсункару Мирзе в походе 1429 года?', fact_ru = 'В азербайджанском походе 1429 года мой отец Шахрух поставил меня командовать левым крылом войска. Значит, отец доверял мне и в ратном деле.' WHERE id = 2144;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Байсункар Мирза и где расположен его мавзолей?', fact_ru = 'Я скончался в 1433 году. Мой мавзолей называют «мавзолеем Байсункара», и расположен он подле медресе, построенного моей матерью Гавхаршад-бегим.' WHERE id = 2145;

-- ===== Xoja Ahror Valiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Ходжа Ахрар Вали?', fact_ru = 'Я родился в 1404 году в селении Багистан близ Шаша — нынешнего Ташкента. Мой предок Ходжа Мухаммад Нами пришёл из Багдада и осел в Шаше.' WHERE id = 1967;
UPDATE fact_cards SET topic_ru = 'Моё имя и мой титул', question_ru = 'Каково настоящее имя Ходжи Ахрара Вали?', fact_ru = 'Моё настоящее имя — Насириддин Убайдуллах ибн Махмуд Шаши. Народ с почтением называл меня «Ходжа Ахрари Вали».' WHERE id = 1968;
UPDATE fact_cards SET topic_ru = 'Мой путь в науке', question_ru = 'Где учился Ходжа Ахрар Вали и кто был его наставником?', fact_ru = 'Сперва я учился в Ташкенте, затем в самаркандских медресе. В 1428 году я отправился в Герат и был в беседах великих шейхов, а после изучил основы тариката накшбандия у Якуба Чархи.' WHERE id = 1969;
UPDATE fact_cards SET topic_ru = 'Тарикат накшбандия', question_ru = 'Какой тарикат возглавлял Ходжа Ахрар Вали и в каком городе он действовал?', fact_ru = 'В XV веке я поднял тарикат накшбандия в Мавераннахре на высокую ступень. В 1451 году я переселился в Самарканд и до конца жизни действовал там.' WHERE id = 1970;
UPDATE fact_cards SET topic_ru = 'Мои медресе и вакфы', question_ru = 'Сколько медресе и ханак построил Ходжа Ахрар Вали?', fact_ru = 'Я построил в Самарканде медресе и 25 января 1470 года выделил ему большие вакфные владения. За свою жизнь я возвёл более 20 медресе и ханак, а в моей вакфной тетради записано 254 имения.' WHERE id = 1971;
UPDATE fact_cards SET topic_ru = 'Моя щедрость', question_ru = 'Какие благотворительные дела совершил Ходжа Ахрар Вали для народа?', fact_ru = 'Хотя я владел многими землями, себя я считал бедняком, ибо всё своё богатство тратил на благо народа. Чтобы решить податной вопрос городских жителей, я уплатил 250 тысяч динаров, а ташкентцам подарил 70 тысяч динаров.' WHERE id = 1972;
UPDATE fact_cards SET topic_ru = 'Мой труд', question_ru = 'Какой труд написал Ходжа Ахрар Вали?', fact_ru = 'Я написал труд по суфизму под названием «Рисолаи волидия».' WHERE id = 1973;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Ходжа Ахрар Вали?', fact_ru = 'Я скончался в 1490 году. Последние годы жизни я провёл в Самарканде.' WHERE id = 1974;

-- ===== Shayboniyxon =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и в какой семье родился Шейбанихан?', fact_ru = 'Я родился в 1451 году. Мой дед — хан кочевых узбеков Абулхайрхан, отец — Шах Будаг султан, мать — Кузибегим. Дед Абулхайрхан дал мне прозвище Шахбахт, и я вырос под его опекой.' WHERE id = 2306;
UPDATE fact_cards SET topic_ru = 'Как я восстановил государство', question_ru = 'Как Шейбанихан восстановил государство?', fact_ru = 'В 1480 году я вновь восстановил государство кочевых узбеков, основанное моим дедом. В 1487–1488 годах я овладел городами Сайрам, Отрар и Туркестан.' WHERE id = 2307;
UPDATE fact_cards SET topic_ru = 'Объединение Мавераннахра', question_ru = 'Как Шейбанихан объединил Мавераннахр?', fact_ru = 'В 1499 году я взял Бухару без боя, а в 1500 году овладел Самаркандом. В 1501 году на реке Кухак я разбил войско Бабура мирзы, в 1503 году присоединил к своему государству Ташкент, а в 1504 году — Фергану.' WHERE id = 2308;
UPDATE fact_cards SET topic_ru = 'Мои походы в Хорасан', question_ru = 'Какие города Хорасана занял Шейбанихан?', fact_ru = 'В 1505 году я занял Ургенч — средоточие Хорезма. В 1506 году я присоединил к своему государству Балх, а в 1507 году — столицу Хорасана Герат.' WHERE id = 2309;
UPDATE fact_cards SET topic_ru = 'Мои преобразования', question_ru = 'Какие преобразования провёл Шейбанихан?', fact_ru = 'В 1507 году я провёл денежную реформу и велел чеканить новые серебряные монеты весом 5,2 грамма. Навёл я порядок и в образовании: дети с 6 лет учились 2 года в школе, а затем в медресе по трём ступеням.' WHERE id = 2310;
UPDATE fact_cards SET topic_ru = 'Как я правил государством', question_ru = 'Как правил своим государством Шейбанихан?', fact_ru = 'В своём государстве я ввёл систему суюргала: области я раздал султанам и бекам — так, Ташкент я передал Суюнходже, а Балх — Султаншаху. Земли и воды, заброшенные из-за тяжести податей, я вновь пустил в дело.' WHERE id = 2311;
UPDATE fact_cards SET topic_ru = 'Мои стихи и мои труды', question_ru = 'Какие произведения написал Шейбанихан?', fact_ru = 'Я был не только полководцем, но и поэтом: я писал газели и рубаи, основательно знал тюркский, персидский и арабский языки. В 1508 году я окончил свой дастан «Бахр уль-худа», написал и книгу наставлений для моего сына Темура султана.' WHERE id = 2312;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и как погиб Шейбанихан?', fact_ru = 'Я пал в 1510 году близ Мерва, в Тахрирабаде на берегу реки Мургаб, в битве против войска иранского шаха Исмаила Сефеви. Меня погребли на Баланд Суфе в Самарканде.' WHERE id = 2313;

-- ===== Abdullaxon II =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Абдуллахан II?', fact_ru = 'Я родился в 1534 году в Миянколе, в селении Афарикент. Мой отец Искандархан был из династии Шейбанидов.' WHERE id = 2092;
UPDATE fact_cards SET topic_ru = 'Моя столица Бухара', question_ru = 'Какой город Абдуллахан II сделал столицей?', fact_ru = 'В мае 1557 года я овладел Бухарой и сделал её своей столицей. В моё время Бухара стала средоточием культуры и науки.' WHERE id = 2093;
UPDATE fact_cards SET topic_ru = 'Мои походы и победы', question_ru = 'Какие города занял Абдуллахан II?', fact_ru = 'Борясь с султанами, отказывавшимися подчиняться центральной власти, я занял Балх в 1574 году, Самарканд в 1578 году, Ташкент, Сайрам, Туркестан и Фергану в 1583 году. На Хорезм я ходил дважды — в 1594 и 1596 годах — и вновь утвердил там власть центра.' WHERE id = 2094;
UPDATE fact_cards SET topic_ru = 'Границы моей державы', question_ru = 'Какими были владения государства при Абдуллахане II?', fact_ru = 'В моё время владения нашего государства простирались от Кашгара до берегов Аральского и Каспийского морей, от Туркестана и Сайрама до восточной части Хорасана.' WHERE id = 2095;
UPDATE fact_cards SET topic_ru = 'Моё благоустроительство', question_ru = 'Какие строительные работы осуществил Абдуллахан II?', fact_ru = 'Я велел возвести в своей стране множество разных сооружений. В моё время в Бухаре было устроено знаменитое медресе Абдуллахана, а градостроительство в стране пошло в рост.' WHERE id = 2096;
UPDATE fact_cards SET topic_ru = 'Моя денежная реформа', question_ru = 'Какую реформу провёл Абдуллахан II?', fact_ru = 'Я укрепил систему государственного управления и провёл денежную реформу.' WHERE id = 2097;
UPDATE fact_cards SET topic_ru = 'Мои стихи и покровительство науке', question_ru = 'Под каким псевдонимом писал стихи Абдуллахан II?', fact_ru = 'Как одарённый поэт я писал стихи на узбекском и персидском языках под псевдонимом «Хан». В моё время Хафиз Таныш Бухари создал свой знаменитый труд «Абдулланаме».' WHERE id = 2098;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Абдуллахан II?', fact_ru = 'Я скончался 8 февраля 1598 года в Самарканде. Меня погребли в комплексе Бахауддина близ Бухары.' WHERE id = 2099;
